Future<void> _completeQolipScan(WidgetTester tester) async {
  await tester.tap(
    find.byKey(const ValueKey('production-quick-scanner-manual-toggle')),
  );
  await tester.pumpAndSettle();
  final input = find.byKey(
    const ValueKey('production-quick-scanner-manual'),
  );
  expect(input, findsOneWidget);
  await tester.enterText(input, 'TEST-QOLIP-QR');
  await tester.tap(find.byTooltip('Qabul qilish'));
  await tester.pumpAndSettle();
  expect(find.byType(ProductionQuickScannerPanel), findsNothing);
  final qolipsHeader = find.byKey(
    const ValueKey('production-qolips-expansion'),
  );
  expect(qolipsHeader, findsOneWidget);
  expect(
    find.descendant(of: qolipsHeader, matching: find.text('1/1 ta')),
    findsOneWidget,
  );
  await tester.tap(qolipsHeader);
  await tester.pumpAndSettle();
  expect(
    find.byKey(
      const ValueKey('production-scanned-qolip-test-qolip-qr'),
    ),
    findsOneWidget,
  );
}

ProductionMapDefinition _alternativeProductionOrderMap({
  required String id,
  required String title,
  required String productCode,
  required String product,
  required List<String> apparatusIds,
  List<String> apparatusNames = const [],
  double? rollCount,
  double? widthMm,
}) {
  assert(
      apparatusNames.isEmpty || apparatusNames.length == apparatusIds.length);
  final apparatusNodes = [
    for (var index = 0; index < apparatusIds.length; index++)
      ProductionMapNode(
        id: 'apparatus-$index',
        kind: 'apparatus',
        title: apparatusNames.isEmpty
            ? _fixtureApparatusName(apparatusIds[index])
            : apparatusNames[index],
        apparatusId: apparatusIds[index],
        alternativeGroupId: 'alt-$id',
        alternativeGroupLabel: 'pechat',
      ),
  ];
  return ProductionMapDefinition(
    id: id,
    productCode: productCode,
    title: title,
    rollCount: rollCount,
    widthMm: widthMm,
    nodes: [
      const ProductionMapNode(id: 'start', kind: 'start', title: 'Start'),
      ...apparatusNodes,
      ProductionMapNode(
        id: 'end',
        kind: 'end',
        title: product,
        itemCode: productCode,
      ),
    ],
    edges: [
      for (final node in apparatusNodes) ...[
        ProductionMapEdge(from: 'start', to: node.id),
        ProductionMapEdge(from: node.id, to: 'end'),
      ],
    ],
  );
}

ProductionMapDefinition _chainedAlternativeProductionOrderMap({
  required String id,
  required String title,
  required String productCode,
  required String product,
  required List<String> firstGroupApparatusIds,
  List<String> firstGroupApparatusNames = const [],
  required List<String> secondGroupApparatusIds,
  List<String> secondGroupApparatusNames = const [],
  required String firstGroupAssignedApparatusId,
  String firstGroupAssignedTitle = '',
  double? rollCount,
  double? widthMm,
}) {
  assert(firstGroupApparatusNames.isEmpty ||
      firstGroupApparatusNames.length == firstGroupApparatusIds.length);
  assert(secondGroupApparatusNames.isEmpty ||
      secondGroupApparatusNames.length == secondGroupApparatusIds.length);
  final firstGroupNodes = [
    for (var index = 0; index < firstGroupApparatusIds.length; index++)
      ProductionMapNode(
        id: 'first-apparatus-$index',
        kind: 'apparatus',
        title: firstGroupApparatusNames.isEmpty
            ? _fixtureApparatusName(firstGroupApparatusIds[index])
            : firstGroupApparatusNames[index],
        apparatusId: firstGroupApparatusIds[index],
        alternativeGroupId: 'alt-first-$id',
        alternativeGroupLabel: 'pechat',
        alternativeAssignedTitle: firstGroupAssignedTitle.isEmpty
            ? _fixtureApparatusName(firstGroupAssignedApparatusId)
            : firstGroupAssignedTitle,
        alternativeAssignedApparatusId: firstGroupAssignedApparatusId,
      ),
  ];
  final secondGroupNodes = [
    for (var index = 0; index < secondGroupApparatusIds.length; index++)
      ProductionMapNode(
        id: 'second-apparatus-$index',
        kind: 'apparatus',
        title: secondGroupApparatusNames.isEmpty
            ? _fixtureApparatusName(secondGroupApparatusIds[index])
            : secondGroupApparatusNames[index],
        apparatusId: secondGroupApparatusIds[index],
        alternativeGroupId: 'alt-second-$id',
        alternativeGroupLabel: 'laminatsiya',
      ),
  ];
  return ProductionMapDefinition(
    id: id,
    productCode: productCode,
    title: title,
    rollCount: rollCount,
    widthMm: widthMm,
    nodes: [
      const ProductionMapNode(id: 'start', kind: 'start', title: 'Start'),
      ...firstGroupNodes,
      ...secondGroupNodes,
      ProductionMapNode(
        id: 'end',
        kind: 'end',
        title: product,
        itemCode: productCode,
      ),
    ],
    edges: [
      for (final first in firstGroupNodes)
        ProductionMapEdge(from: 'start', to: first.id),
      for (final first in firstGroupNodes)
        for (final second in secondGroupNodes)
          ProductionMapEdge(from: first.id, to: second.id),
      for (final second in secondGroupNodes)
        ProductionMapEdge(from: second.id, to: 'end'),
    ],
  );
}

ProductionMapDefinition _productionOrderMap({
  required String id,
  required String title,
  required String productCode,
  required String apparatusId,
  String apparatusName = '',
  required String product,
  String orderNumber = '',
  double? rollCount,
  double? widthMm,
  double? orderKg,
  double? baseLength,
  int apparatusCopies = 1,
}) {
  final apparatusNodes = [
    for (var index = 0; index < apparatusCopies; index++)
      ProductionMapNode(
        id: index == 0 ? 'apparatus' : 'apparatus-$index',
        kind: 'apparatus',
        title: apparatusName.isEmpty
            ? _fixtureApparatusName(apparatusId)
            : apparatusName,
        apparatusId: apparatusId,
      ),
  ];
  return ProductionMapDefinition(
    id: id,
    productCode: productCode,
    title: title,
    orderNumber: orderNumber,
    rollCount: rollCount,
    widthMm: widthMm,
    orderKg: orderKg,
    baseLength: baseLength,
    nodes: [
      const ProductionMapNode(id: 'start', kind: 'start', title: 'Start'),
      ...apparatusNodes,
      ProductionMapNode(
        id: 'end',
        kind: 'end',
        title: product,
        itemCode: productCode,
      ),
    ],
    edges: [
      ProductionMapEdge(from: 'start', to: apparatusNodes.first.id),
      for (var index = 0; index < apparatusNodes.length - 1; index++)
        ProductionMapEdge(
          from: apparatusNodes[index].id,
          to: apparatusNodes[index + 1].id,
        ),
      ProductionMapEdge(from: apparatusNodes.last.id, to: 'end'),
    ],
  );
}

